package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	Category string `json:"category"`
}

// sanitizeInput removes null bytes and trims whitespace
func sanitizeInput(s string) string {
	s = strings.ReplaceAll(s, "\x00", "")
	return strings.TrimSpace(s)
}

// buildProductQuery constructs a filtered product search
// The category filter uses parameterized query but sortBy is
// restricted to known columns via the allowlist check below
func buildProductQuery(category, sortBy, direction string) string {
	base := "SELECT id, name, price, category FROM products WHERE active = true"
	if category != "" {
		base += fmt.Sprintf(" AND category = '%s'", category)
	}
	// Sort direction validated
	if direction != "ASC" && direction != "DESC" {
		direction = "ASC"
	}
	// sortBy validated against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if allowedSorts[sortBy] {
		base += fmt.Sprintf(" ORDER BY %s %s", sortBy, direction)
	} else {
		base += " ORDER BY id ASC"
	}
	return base + " LIMIT 50"
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := sanitizeInput(r.URL.Query().Get("cat"))
	sortBy := sanitizeInput(r.URL.Query().Get("sort"))
	direction := strings.ToUpper(sanitizeInput(r.URL.Query().Get("dir")))

	query := buildProductQuery(category, sortBy, direction)
	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category); err != nil {
			continue
		}
		products = append(products, p)
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// addReview uses parameterized queries - safe
func addReview(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Method not allowed", 405)
		return
	}
	var review struct {
		ProductID int    `json:"product_id"`
		Rating    int    `json:"rating"`
		Comment   string `json:"comment"`
	}
	if err := json.NewDecoder(r.Body).Decode(&review); err != nil {
		http.Error(w, "Bad request", 400)
		return
	}
	_, err := db.Exec("INSERT INTO reviews (product_id, rating, comment) VALUES ($1, $2, $3)",
		review.ProductID, review.Rating, review.Comment)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}
	w.WriteHeader(201)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/products/search", searchProducts)
	http.HandleFunc("/products/review", addReview)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
